import { useId } from 'react'
import type { SVGProps } from 'react'

/**
 * Icons for the WeChat-style chrome.
 *
 * Where WeChat ships the glyph, the SVG is taken verbatim from the payloads
 * embedded in `Weixin.dll` (see `WechatIcons.tsx`, generated by
 * `.cache/wxsvg/gen_icons.py`) and re-exported below. Two glyphs are not from
 * that set: `MomentsTabIcon` is WeChat's design-system compass
 * (`.cache/wxres/tabBar_icons_outlined_discover.svg`), and `TelegramLogo` is the
 * third-party brand mark from Simple Icons (CC0). The brand mark is used for the
 * rail's 聊天 tab, the login card and the empty-pane watermark. The selected-state
 * variants (`*TabFilledIcon`) are rebuilt from the outlined tab geometry, because
 * this build's payload set did not carry the client's filled tab art.
 */

type IconProps = SVGProps<SVGSVGElement> & { size?: number }

export {
  AddFriendIcon,
  CallBubbleIcon,
  CallIcon,
  CallOutlineIcon,
  ChevronDownIcon,
  ContactsManageIcon,
  ContactsTabIcon,
  CubeTabIcon,
  DeviceIcon,
  EmojiIcon,
  FolderIcon,
  MenuIcon,
  MessageOutlineIcon,
  MicIcon,
  MoreIcon,
  NewGroupIcon,
  NoteIcon,
  PlusIcon,
  ScissorsIcon,
  SearchIcon,
  VideoCallOutlineIcon,
} from './WechatIcons'

import { CallBubbleIcon } from './WechatIcons'

/**
 * Trailing chevron of a navigational row (the chat-info panel's 查找聊天内容).
 * Hand-drawn at the client's weight: a 7 × 11 stroke, 1.3 px, no fill.
 */
/**
 * 发语音: the client's circled microphone with sound arcs, which sits next to
 * 发送. Hand-drawn from the reference screenshots at the same weight as the
 * other toolbar glyphs — the payload had no circled variant.
 */
export function VoiceMessageIcon({ size = 20, ...rest }: IconProps) {
  return (
    <svg width={size} height={size} viewBox="0 0 24 24" fill="none" aria-hidden {...rest}>
      <circle cx="12" cy="12" r="9" stroke="currentColor" strokeWidth="1.5" />
      {/*
        The dot and its two sound arcs share one centre (9.7, 12) and mirror on
        the horizontal axis, so the glyph is symmetric — arcs drawn by eye from
        arbitrary start points came out visibly lopsided. The group's own centre
        lands on the circle's (11.9 vs 12), which is what keeps it looking upright.
      */}
      <circle cx="9.7" cy="12" r="1.15" fill="currentColor" />
      <path
        d="M11.86 9.92A3 3 0 0 1 11.86 14.08"
        stroke="currentColor"
        strokeWidth="1.4"
        strokeLinecap="round"
      />
      <path
        d="M13.8 8.19A5.6 5.6 0 0 1 13.8 15.81"
        stroke="currentColor"
        strokeWidth="1.4"
        strokeLinecap="round"
      />
    </svg>
  )
}

export function ChevronRightIcon({ size = 12, ...rest }: IconProps) {
  return (
    <svg
      width={(size * 8) / 14}
      height={size}
      viewBox="0 0 8 14"
      fill="none"
      aria-hidden="true"
      focusable="false"
      {...rest}
    >
      <path
        d="M2 1.5 6.2 7 2 12.5"
        stroke="currentColor"
        strokeWidth={1.3}
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  )
}

